    /** Render only typed, trusted validation reasons; arbitrary diagnostics stay literal. */
    public static String validation(IllegalArgumentException failure) {
        if (failure instanceof com.mineagent.api.i18n.LocalizedValidationException typed) {
            return text(typed.key(), typed.arguments());
        }
        return String.valueOf(failure.getMessage());
    }

    public static String text(String key, Object... arguments) {
        return CATALOG.text(RuntimeLanguage.language(), key, arguments);
    }
